Let $d'_l$ be the last hop to destination $d_l$ on path $\mathcal{P}_l^h$, we have for each destination node
\begin{equation}\label{eq:DstFlow}
  \sum_r\sum_m x_{d'_l,d_l,m}^{l,h,r}=n_l^h y_l^h, \;\; \forall \; h \in \mathcal{P}_l, \forall \; l.

theorem.raw:
Let $\mathbf{e}^{\ast}$ be the optimal solution.  The distributed algorithm in Table~\ref{tab:PathSelecAlgo} converges if the step sizes $\alpha(\tau)$ in~(\ref{eq:SubGrad}) satisfy the following condition:
\begin{eqnarray}\label{eq:StepSize}
  0 < \alpha(\tau) < \frac{2 \left[ q(\mathbf{e}(\tau))-q(\mathbf{e}^{\ast}) \;
       \right]}{||G(\tau)||^2}, \;\; \mbox{for all } \tau,
\end{eqnarray}
where $G(\tau)$ is the gradient of $q(\mathbf{e}(\tau))$.

proof.raw:
(i) {\em Complexity}: In Step 4 in Table~\ref{tab:GreedyAlgo1}, it takes $O(MG)$ to solve for $\vec{e}_{\hat{g},\hat{m}}$. Since each iteration assigns one tile to sub-layer $\hat{m}$ of group $\hat{g}$, it takes $T_e$ iterations to allocate all the available tiles in a GoP window. Therefore, the overall complexity of GRD1 is $O(MGT_e)$.

(ii) {\em Optimality Bound}: This proof is extended from a result first shown in~\cite{Deb08} for layered videos. We first show a property of group utility $U_g(\vec{l})$, which will be used in the proof of the optimality gap.  For two vectors $\vec{l}^1_g$ and $\vec{l}^2_g$, letting $\Delta = U_g(\vec{l}^1_g)-U_g(\vec{l}^2_g)$, we have









\begin{eqnarray}\label{eq:lema2}
& & \hspace{-0.2in} \Delta = \sum_{k=1}^M (n_{g,k}-n_{g,k+1}) \times \log \left( 1 + \frac{ \sum_{m=1}^k \beta_g b_{g,m}(l_{g,m}^1-l_{g,m}^2) }{ Q^b_g + \sum_{m=1}^k \beta_g b_{g,m} l_{g,m}^2 } \right) \nonumber  \\
& & \hspace{-0.2in} \le \sum_{k=1}^M \sum_{m=1}^k (l_{g,m}^1-l_{g,m}^2)^+(n_{g,k}-n_{g,k+1}) \times \log \left( 1+ \beta_g b_{g,m} / \left[ Q^b_g+\sum_{m=1}^k \beta_g b_{g,m} l_{g,m}^2 \right] \right) \nonumber \\
& & \hspace{-0.2in} \le \sum_{k=1}^M \sum_{m=1}^M (l_{g,m}^1-l_{g,m}^2)^+(n_{g,k}-n_{g,k+1}) \times  \log \left( 1 + \beta_g b_{g,m} / \left[ Q^b_g + \sum_{m=1}^k \beta_g b_{g,m} l_{g,m}^2 \right] \right) \nonumber\\
& & \hspace{-0.2in} = \sum_{m=1}^M (l_{g,m}^1-l_{g,m}^2)^+ \left[ U_g(\vec{l}^2_g+b_{g,m})-U(\vec{l}^2_g) \right],
\end{eqnarray}
where $y^+=\max \{ 0, y \}$. The first inequality is due to the concavity of logarithm functions. 

Next we prove the optimality bound. Let $\vec{l}_{t}$ be the output of GRD1 after $t$ iterations. Let the utility gap between the optimal solution and the GRD1 solution be $F_{t} = U(\vec{l}^{\ast}) - U(\vec{l}_{t})$, and $\vec{e}_{\hat{g},\hat{m}}(t)$ the argument found in Step 4 of GRD1 after $t$ iterations. We have $\vec{l}_{t} = \vec{l}_{t-1} + \vec{e}_{\hat{g}, \hat{m}}(t)$ and
\begin{eqnarray}
 & & \hspace{-0.1in} F_{t-1} = U(\vec{l}^{\ast})-U(\vec{l}_{t-1}) \nonumber \\
 & & \hspace{-0.3in} \le \sum_g\sum_m (l_{g,m}^{\ast}-l_{g,m})^{+}
[U(\vec{l}_{t-1}+\vec{e}_{g,m}(t))-U(\vec{l}_{t-1})] \nonumber \\
 & & \hspace{-0.3in} \le \sum_g\sum_m (l_{g,m}^{\ast}-l_{g,m})^{+} [U(\vec{l}_{t-1}+\vec{e}_{\hat{g},\hat{m}}(t))- U(\vec{l}_{t-1})]
\frac{b_{g,m}+R/T_e}{b_{\hat{g},\hat{m}}(t)+R/T_e}\nonumber \\
 & & \hspace{-0.3in} \le \frac{U(\vec{l}_t)-U(\vec{l}_{t-1})}{ b_{\hat{g}, \hat{m}}(t) + R/T_e}
\sum_g\sum_m [l_{g,m}^{\ast}(b_{g,m}+R/T_e)]. \nonumber
\end{eqnarray}
The first inequality is due to (\ref{eq:lema2}) and the second inequality follows Step 4 of GRD1.  It follows (\ref{eq:st1}) that $\sum_g\sum_m l_{g,m}^{\ast} \le T_e$ and $\sum_g\sum_m b_{g,m}l_{g,m}^{\ast} \le R$.  We have $F_{t-1} \le (F_{t-1}-F_{t}) \frac{2R}{b_{\hat{g}, \hat{m}}(t)+R/T_e}$.  Solving for $F_t$, we have $F_{t}\le F_{t-1} \left\{ 1 - \left[ b_{\hat{g},\hat{m}}(t)+R/T_e \right] / (2R) \right\}$. 

Suppose the {\em WHILE} loop in Table~\ref{tab:GreedyAlgo1} has been executed $k$ times when the solution is obtained. 
\begin{eqnarray}
F_k &\le& F_{k-1} \left\{ 1-\left[b_{\hat{g},\hat{m}}(k)+R/T_e\right] / (2R) \right\} \nonumber \\
& \le & F_0 \prod_{t=1}^k \left\{ 1 - \left[ b_{\hat{g},\hat{m}}(t)+R/T_e \right] / (2R) \right\} \nonumber \\
&\le& F_0 \left\{ 1 - 1/(2kR) \sum_{t=1}^k [ b_{\hat{g},\hat{m}}(t)+R/T_e ] \right\}^k. \nonumber
\end{eqnarray}
The {\em WHILE} loop exits when one or both of two constraints are violated. If $\sum_{g}\sum_{m} l_{g,m} \le T_e$ is violated, there is no tile that can be used. Therefore $k \ge T_e$ and $\sum_{t=1}^kR/T_e\ge R$. If constraint ``$A$ is not empty'' is violated, all the videos have been allocated sufficient number of tiles and will be transmitted at full rates. We have $\sum_{t=1}^k b_{\hat{g},\hat{m}}(t) \geq R$ in this case.  It follows that
\begin{eqnarray}
F_k &\le& 
F_0 \left\{ 1 - 1/(2kR) \sum_{t=1}^k [ b_{\hat{g},\hat{m}}(t)+R/T_e ] \right\}^k \nonumber \\
& \le & F_0 \left[ 1 - 1/(2k) \right]^k \; \le \; F_0 e^{-1/2}. \nonumber 
\end{eqnarray}
Since $F_0=U(\vec{l}^{\ast})$, we have $U(\vec{l}_k)\ge(1-e^{-1/2})U(\vec{l}^{\ast})$.  Therefore, we conclude that the GRD1 solution is bounded by $(1-e^{-1/2})U(\vec{l}^{\ast})$ and $U(\vec{l}^{\ast})$.

Suppose there exists a pair of $i$ and $j$ where $\mbox{Inc}(\xi_i) > \mbox{Inc}(\xi_j)$ and $c_i(t) < c_j(t)$. We can further increase E[Reward] by switching the tile assignment, i.e., assign channel $i$ to $\xi_j$ and channel $j$ to $\xi_i$. With this new assignment, the net increase in E[Reward] is 
\begin{eqnarray}
  & & \hspace*{-0.3in} c_j(t)\mbox{Inc}(\xi_i) + c_i(t)\mbox{Inc}(\xi_j)-c_i(t)\mbox{Inc}(\xi_i)-c_j(t)\mbox{Inc}(\xi_j) \nonumber \\
  & = & [c_j(t) - c_i(t)][\mbox{Inc}(\xi_i) - \mbox{Inc}(\xi_j)] > 0. \nonumber
\end{eqnarray}
Therefore E[Reward] is maximized when the $\{ \mbox{Inc}(\xi_i) \}$ and $\{c_i(t)\}$ are in the same order.

According to Fact~\ref{thm:EqualCont}, the linearized problem of OPT-PS, i.e., OPT-rPS, can be rewritten as an equality constrained problem in the following form:
\begin{eqnarray}
	\mbox{maximize:} && \mathbf{F}'\mathbf{y} \label{eq:EqualCons} \\
	\mbox{subject to:} && \mathbf{w}_j' \mathbf{y}=1, \;\; j \in
     \mathcal{A}(\mathbf{y}^{\ast}) \label{eq:EqualCons1} \\
     && 0 \leq y_l^h \leq 1, \; \mbox{for all } h,l,  \nonumber
\end{eqnarray}
where $\mathbf{F}$, $\mathbf{w}_j$'s, and $\mathbf{y}$ are column vectors with elements $F_l^h$, $w_{l,h}^g$, and $y_l^h$, respectively.  We apply {\em Gauss-Jordan elimination} to the constraints in (\ref{eq:EqualCons1}) to solve for $\mathbf{y}$. Since there is not sufficient number of equations, some $y_l^h$'s are free variables (denoted as $y_i^f$) and the rest are dependent variables (denoted as $y_j^d$). Assuming there are $r$ free variables, the dependent variables can be written as linear combinations of the free variables after Gauss-Jordan elimination, as 
\begin{equation}\label{eq:depdent}
  y_j^d = \sum_{i=1}^r \bar{w}_j^i y_i^f + \bar{b}_j, 
          \; j \in \mathcal{A}(y_i^{\ast}).
\end{equation}
Due to Gauss-Jordan elimination and binary vectors $\mathbf{w}_j$'s, $\bar{w}_j^i$ and $\bar{b}_j$ in (\ref{eq:depdent}) are all integers.  Therefore, if all the free variables $y_i^f$ attain binary values, then all the dependent variables $y_j^d$ computed using (\ref{eq:depdent}) will also be integers.  Since $0 \leq y_j^d \leq 1$, being integers means that they are either 0 or 1, i.e., binaries. That is, such a solution will be feasible. 

Next we substitute (\ref{eq:depdent}) into problem (\ref{eq:EqualCons}) to eliminate all the dependent variables.   Then we obtain a unconstrained problem with only $r$ free variables, as
\begin{equation}
  \mbox{maximize:} \;\; \sum_{i=1}^r \bar{F}_i y_i^f + \bar{b}_0 
	\label{eq:GaussElimi}
\end{equation}
Since the free variables $y_i^f$'s take value in \{0, 1\}, this problem can be easily solved as follows. If the coefficient $\bar{F}_i > 0$, we set $y_i^f=1$; otherwise, if $\bar{F}_i < 0$, we set $y_i^f=0$.  Thus (\ref{eq:GaussElimi}) achieves its maximum objective value.  Once all the free variables are determined with their optimal binary values, we computes the dependent variables using (\ref{eq:depdent}), which are also binary as discussed above.  Thus we obtain a feasible solution, which is optimal.

items.raw:
The utility function of the entire CR video multicast system is 
\begin{equation}
U = \sum_{g=1}^G U_g.
\end{equation}

\label{thm:EqualCont}
Consider a linear problem involving both equality and inequality constraints
\begin{eqnarray}
	\mbox{maximize:} && \mathbf{a}' \mathbf{x} \label{eq:InequalLP} \\
	\mbox{subject to:} && \mathbf{h}'_1\mathbf{x}=b_1, \; \cdots, \; 
        \mathbf{h}'_m\mathbf{x}=b_m   \nonumber \\
     && \mathbf{g}'_1\mathbf{x}\le c_1, \; \cdots, \; 
        \mathbf{g}'_r\mathbf{x} \le c_r, \nonumber
\end{eqnarray}
where $\mathbf{a}$, $\mathbf{h}_i$, and $\mathbf{g}_j$ are column vectors in $\mathcal{R}_n$, $b_i$'s and $c_j$'s are scalars, and $\mathbf{a}'$ is the {\em transpose} of $\mathbf{a}$. For any feasible point $\mathbf{x}$, the set of {\em active} inequality constraints is denoted by
  $\mathcal{A}(\mathbf{x}) = \left\{ j | \mathbf{g}'_j \mathbf{x}=c_j \right\}$.
If $\mathbf{x}^{\ast}$ is a maximizer of inequality constrained problem (\ref{eq:InequalLP}), $\mathbf{x}^{\ast}$ is also a maximizer of the following equality constrained problem:
\begin{eqnarray}
	\mbox{maximize:} && \mathbf{a}' \mathbf{x} \label{eq:eq:EqualLP} \\
	\mbox{subject to:} && \mathbf{h}'_1 \mathbf{x} = b_1, \; \cdots, \; 
  \mathbf{h}'_m \mathbf{x}=b_m \nonumber \\
  && \mathbf{g}'_j\mathbf{x} = c_j, \forall \; j \in \mathcal{A}(\mathbf{x}). \nonumber
\end{eqnarray}

Letting $\vec{l} = [l_{1,1}, l_{1,2}, \cdots, l_{1,M}, l_{2,1}, \cdots l_{G,M}]$ denote the {\em tile allocation vector}, we formulate an optimization problem OPT-Part as follows.
\begin{eqnarray}
 \mbox{maximize:} && \hspace*{-0.2in} U(\vec{l})
  = \sum_{g=1}^{G}\sum_{k=1}^M(n_{g,k}-n_{g,k+1}) \times 


  \log \left[ Q^b_g+\beta_g \sum_{m=1}^k b_{g,m}l_{g,m} \right] \label{eq:allocat} \\
\mbox{subject to:} 
  && \hspace*{-0.2in} \sum_{g=1}^G\sum_{m=1}^M l_{g,m}\le T_e \label{eq:st1} \\
	&& \hspace*{-0.2in} \sum_{m=1}^M b_{g,m}l_{g,m} \le \bar{R}_g^e, \; g \in [1, \cdots, M] 
	       \label{eq:st2} \\
	&& \hspace*{-0.2in} l_{g,m} \geq 0, \; m \in [1, \cdots, M], g \in [1, \cdots, G]. 
	       \label{eq:st3}
\end{eqnarray}

Finally we formulate the problem of multi-hop CR network video streaming (OPT-CRV) as:
\begin{eqnarray}
	&& \hspace{-0.4in} \mbox{max:} \;\; \sum_l \hspace{-0.03in} \sum_{h \in \mathcal{P}_l}y_l^h \log \hspace{-0.03in} \left( \hspace{-0.03in} 1 \hspace{-0.01in} + \hspace{-0.01in} \rho_l^t \sum_r \sum_m x_{z_l,z'_l,m}^{l,h,r} (1 \hspace{-0.01in} - \hspace{-0.01in} p_{l,h}^r) \hspace{-0.03in} \right) \label{eq:PriProb} \\
	&& \hspace{-0.4in} \mbox{subject to:} \;\;\; (\ref{eq:DefX1}) \sim (\ref{eq:PathCon}).  \nonumber
\end{eqnarray}

Since the domains of $x_{i,j,m}^{l,h,r}$ defined in (\ref{eq:OneChan1})$\sim$(\ref{eq:IntmFlow}) for different paths do not intersect with each other, we can decompose Problem OPT-CRV into two subproblems.  The first subproblem deals with channel scheduling for maximizing the expected utility on a chosen path $\mathcal{P}_l^h$.  We have the {\em channel scheduling} problem (OPT-CS) as:
\begin{eqnarray}
	&& \hspace{-0.2in} H_l^h=\max_{\mathbf{x}} \sum_r \sum_m
      x_{z_l,z'_l,m}^{l,h,r}(1-p_{l,h}^r)  \label{eq:optcs} \\
&& \hspace{-0.2in} \mbox{subject to:} \; (\ref{eq:OneChan1})\sim(\ref{eq:IntmFlow}), \; x_{z_l,z'_l,m}^{l,h,r} \in \{0,1\}, \; \mbox{for all } l, h, r, m. \nonumber
\end{eqnarray}

In the second part, optimal paths are selected to maximize the overall objective function.  Letting $F_l^h = \log \left( 1 + \rho_l^T H_l^h \right)$, we have the following {\em path selection} problem (OPT-PS):
\begin{eqnarray}
	\mbox{maximize:} && f(\mathbf{y}) = 
    \sum_l \sum_h F_l^h y_l^h  \label{eq:PathSelec} \\
	  \mbox{subject to:} && \sum_l\sum_{h 
	           \in \mathcal{P}_l} 
	  w_{l,h}^g y_l^h \le 1, \; \mbox{for all } \; g \nonumber \\
	  && y_l^h \in \{0,1\}, \; \mbox{for all } \; l, h. \nonumber
\end{eqnarray}

If $\mathbf{x}^{\ast}$ is a maximizer of inequality constrained problem (\ref{eq:InequalLP}), $\mathbf{x}^{\ast}$ is also a maximizer of the following equality constrained problem:
\begin{eqnarray}
	\mbox{maximize:} && \mathbf{a}' \mathbf{x} \label{eq:eq:EqualLP} \\
	\mbox{subject to:} && \mathbf{h}'_1 \mathbf{x} = b_1, \; \cdots, \; 
  \mathbf{h}'_m \mathbf{x}=b_m \nonumber \\
  && \mathbf{g}'_j\mathbf{x} = c_j, \forall \; j \in \mathcal{A}(\mathbf{x}). \nonumber
\end{eqnarray}

\begin{eqnarray}\label{eq:lema2}
& & \hspace{-0.2in} \Delta = \sum_{k=1}^M (n_{g,k}-n_{g,k+1}) \times \log \left( 1 + \frac{ \sum_{m=1}^k \beta_g b_{g,m}(l_{g,m}^1-l_{g,m}^2) }{ Q^b_g + \sum_{m=1}^k \beta_g b_{g,m} l_{g,m}^2 } \right) \nonumber  \\
& & \hspace{-0.2in} \le \sum_{k=1}^M \sum_{m=1}^k (l_{g,m}^1-l_{g,m}^2)^+(n_{g,k}-n_{g,k+1}) \times \log \left( 1+ \beta_g b_{g,m} / \left[ Q^b_g+\sum_{m=1}^k \beta_g b_{g,m} l_{g,m}^2 \right] \right) \nonumber \\
& & \hspace{-0.2in} \le \sum_{k=1}^M \sum_{m=1}^M (l_{g,m}^1-l_{g,m}^2)^+(n_{g,k}-n_{g,k+1}) \times  \log \left( 1 + \beta_g b_{g,m} / \left[ Q^b_g + \sum_{m=1}^k \beta_g b_{g,m} l_{g,m}^2 \right] \right) \nonumber\\
& & \hspace{-0.2in} = \sum_{m=1}^M (l_{g,m}^1-l_{g,m}^2)^+ \left[ U_g(\vec{l}^2_g+b_{g,m})-U(\vec{l}^2_g) \right],
\end{eqnarray}

\begin{eqnarray} \label{eq:mreward}
  \mbox{maximize:} \;\;\; \mbox{E} [\mbox{Reward}(\vec{\xi})] = \sum_{n=1}^N c_n(t) \cdot \mbox{Inc}(\xi_n),
\end{eqnarray}

\begin{eqnarray}\label{eq:DefChi}
  \Omega_{i,j} = \left\{ m \left| A_m^k=0 \mbox{ and } A_m^{k'}=0 \right. \right\}. 
\end{eqnarray}

\begin{eqnarray}\label{eq:DefX1}
  x_{i,j,m}^{l,h,r}=\left\{
    \begin{array}{ll}
